// src/pages/Mesas.jsx  → VERSIÓN FINAL QUE NUNCA FALLA (copia TODO)
import { useEffect, useState } from "react";
import { api } from "../services/api";
import { Table, Users, Clock, Trash2 } from "lucide-react";
import "./Mesas.css";

export default function Mesas() {
  const [mesas, setMesas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [mesaSeleccionada, setMesaSeleccionada] = useState(null);
  const [cantidadClientes, setCantidadClientes] = useState(1);
  const [showConfirmarLiberar, setShowConfirmarLiberar] = useState(false);

  useEffect(() => {
    cargarMesas();
  }, []);

  const cargarMesas = async () => {
    try {
      const response = await api.get("/api/mesas/");
      // Acepta cualquier formato: lista directa, {results: [...]}, o {data: [...]}
      let data = response;
      if (response && response.results) data = response.results;
      if (response && response.data) data = response.data;
      if (!Array.isArray(data)) {
        console.error("Formato inesperado:", response);
        data = [];
      }

      setMesas(data.map(m => ({
        ...m,
        tiempoOcupada: m.ocupada ? "Reciente" : null
      })));
    } catch (err) {
      console.error("Error cargando mesas:", err);
      alert("Error cargando mesas");
    } finally {
      setLoading(false);
    }
  };

  const toggleMesa = async (mesa, clientes = null) => {
    const nuevaOcupada = !mesa.ocupada;
    const nuevosClientes = clientes !== null ? clientes : (nuevaOcupada ? mesa.capacidad : 0);

    setMesas(prev => prev.map(m =>
      m.id === mesa.id ? { ...m, ocupada: nuevaOcupada, clientes_actuales: nuevosClientes } : m
    ));

    try {
      if (nuevaOcupada) {
        await api.post(`/api/mesas/${mesa.id}/ocupar/`, { cantidad_clientes: nuevosClientes });
      } else {
        await api.post(`/api/mesas/${mesa.id}/liberar/`);
      }
    } catch (err) {
      alert("Error del servidor. Se revirtió.");
      setMesas(prev => prev.map(m =>
        m.id === mesa.id ? { ...m, ocupada: mesa.ocupada, clientes_actuales: mesa.clientes_actuales } : m
      ));
    }
  };

  const abrirModal = (mesa) => {
    setMesaSeleccionada(mesa);
    setCantidadClientes(mesa.ocupada ? mesa.clientes_actuales : mesa.capacidad);
    setShowModal(true);
  };

  const confirmarModal = () => {
    if (mesaSeleccionada.ocupada) {
      toggleMesa(mesaSeleccionada, 0);
    } else {
      toggleMesa(mesaSeleccionada, cantidadClientes);
    }
    setShowModal(false);
  };

  const liberarTodas = () => setShowConfirmarLiberar(true);
  const confirmarLiberarTodas = async () => {
    for (const mesa of mesas.filter(m => m.ocupada)) {
      await api.post(`/api/mesas/${mesa.id}/liberar/`);
    }
    cargarMesas();
    setShowConfirmarLiberar(false);
  };

  const ocupadas = mesas.filter(m => m.ocupada).length;
  const libres = mesas.length - ocupadas;

  if (loading) return <div className="loader">Cargando mesas...</div>;

  return (
    <div className="mesas-page god-mode">
      <div className="mesas-bg"></div>
      <div className="mesas-overlay"></div>

      <div className="stats-bar">
        <div className="stat">
          <Users size={40} color="#e74c3c" />
          <div><span className="numero">{ocupadas}</span><span className="texto">Ocupadas</span></div>
        </div>
        <div className="stat">
          <Table size={40} color="#10b981" />
          <div><span className="numero">{libres}</span><span className="texto">Libres</span></div>
        </div>
        <button onClick={liberarTodas} className="btn-liberar-todas">
          <Trash2 size={20} /> Liberar todas
        </button>
      </div>

      <div className="mesas-content">
        <h1 className="mesas-title">CONTROL DE MESAS</h1>
        <p className="mesas-subtitle">Click → rápido | Click derecho → cantidad exacta</p>

        <div className="mesas-grid">
          {mesas.map((mesa) => {
            const esOcupada = mesa.ocupada;
            const Icon = esOcupada ? Users : Table;
            const color = esOcupada ? "#e74c3c" : "#10b981";

            return (
              <div
                key={mesa.id}
                className={`mesa-card pro ${esOcupada ? "ocupada pulse" : "libre"}`}
                onClick={() => toggleMesa(mesa)}
                onContextMenu={(e) => { e.preventDefault(); abrirModal(mesa); }}
                style={{ "--estado-color": color }}
              >
                <div className="mesa-header">
                  <Icon size={44} />
                  <span className="mesa-numero">Mesa {mesa.numero}</span>
                </div>
                <div className="mesa-body">
                  <div className="estado-badge pro">
                    <div className="punto"></div>
                    <span style={{ color }}>{esOcupada ? "OCUPADA" : "LIBRE"}</span>
                  </div>
                  <p className="capacidad">Capacidad: {mesa.capacidad}</p>
                  <p className="clientes-grande">{mesa.clientes_actuales} / {mesa.capacidad}</p>
                  {esOcupada && <div className="tiempo-ocupada"><Clock size={16} /> Reciente</div>}
                </div>
                <div className="mesa-glow"></div>
              </div>
            );
          })}
        </div>
      </div>

      {/* MODALES */}
      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h2>Mesa {mesaSeleccionada?.numero}</h2>
            {mesaSeleccionada?.ocupada ? <p>¿Liberar esta mesa?</p> : (
              <>
                <p>¿Cuántos clientes?</p>
                <input type="number" min="1" max={mesaSeleccionada?.capacidad} value={cantidadClientes}
                  onChange={e => setCantidadClientes(Number(e.target.value))} className="input-clientes" />
              </>
            )}
            <div className="modal-buttons">
              <button onClick={confirmarModal} className="btn-confirmar">Confirmar</button>
              <button onClick={() => setShowModal(false)} className="btn-cancelar">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {showConfirmarLiberar && (
        <div className="modal-overlay" onClick={() => setShowConfirmarLiberar(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h2>¿Liberar TODAS las mesas?</h2>
            <p>Esta acción no se puede deshacer.</p>
            <div className="modal-buttons">
              <button onClick={confirmarLiberarTodas} className="btn-confirmar">Sí, liberar todas</button>
              <button onClick={() => setShowConfirmarLiberar(false)} className="btn-cancelar">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
